begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(11);
insert into auth.users(id,email) values ('45100000-0000-4000-8000-000000000001','week-owner@example.test'),('45100000-0000-4000-8000-000000000002','week-doctor@example.test'),('45100000-0000-4000-8000-000000000003','week-other@example.test');
insert into public.clinics(id,name,timezone) values ('45200000-0000-4000-8000-000000000001','Week Clinic','America/Mexico_City'),('45200000-0000-4000-8000-000000000002','Other Clinic','America/Mexico_City');
insert into public.clinic_members(id,clinic_id,user_id,role,status) values ('45300000-0000-4000-8000-000000000001','45200000-0000-4000-8000-000000000001','45100000-0000-4000-8000-000000000001','owner','active'),('45300000-0000-4000-8000-000000000002','45200000-0000-4000-8000-000000000001','45100000-0000-4000-8000-000000000002','doctor','active'),('45300000-0000-4000-8000-000000000003','45200000-0000-4000-8000-000000000002','45100000-0000-4000-8000-000000000003','doctor','active');
select extensions.ok(has_function_privilege('authenticated','public.get_professional_availability_week(uuid,uuid,date)','execute') and not has_function_privilege('anon','public.get_professional_availability_week(uuid,uuid,date)','execute'),'week RPC grants are authenticated-only');
select extensions.ok((select prosecdef and proconfig @> array['search_path=public, pg_temp'] from pg_proc where oid='public.get_professional_availability_week(uuid,uuid,date)'::regprocedure),'week RPC has fixed definer boundary');
insert into public.professional_availability_rules(clinic_id,clinic_member_id,weekday,start_time,end_time,effective_from,effective_until,is_active) values ('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',1,'09:00','13:00','2026-09-13',null,true),('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',1,'15:00','18:00','2026-09-13',null,true),('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',2,'10:00','14:00','2026-09-13',null,true),('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',3,'08:00','09:00','2026-08-01','2026-09-12',true),('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',4,'08:00','09:00','2026-09-13',null,false);
set local role authenticated; select set_config('request.jwt.claim.sub','45100000-0000-4000-8000-000000000001',true);
select extensions.is((select count(*)::int from public.get_professional_availability_week('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',date '2026-09-13')),3,'sunday effective date returns all active weekdays');
select extensions.is((select count(*)::int from public.get_professional_availability_week('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',date '2026-09-13') where weekday=1),2,'monday has both intervals');
select extensions.is((select count(*)::int from public.get_professional_availability_week('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',date '2026-09-13') where weekday=2 and start_time='10:00' and end_time='14:00'),1,'tuesday interval is returned');
select extensions.is((select count(*)::int from public.get_professional_availability_week('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',date '2026-09-13') where weekday=3),0,'expired rule excluded');
select extensions.is((select count(*)::int from public.get_professional_availability_week('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',date '2026-09-13') where weekday=4),0,'inactive rule excluded');
select extensions.is((select count(*)::int from public.get_professional_availability_week('45200000-0000-4000-8000-000000000001','45300000-0000-4000-8000-000000000002',date '2026-09-14')),3,'monday date has same effective weekly configuration');
select extensions.throws_ok($$select * from public.get_professional_availability_week('45200000-0000-4000-8000-000000000002','45300000-0000-4000-8000-000000000002',date '2026-09-13')$$,'42501',null,'cross-clinic access rejected');
select extensions.throws_ok($$select * from public.get_professional_availability_week('45200000-0000-0000-0000-000000000000','45300000-0000-4000-8000-000000000002',date '2026-09-13')$$,'42501',null,'wrong clinic rejected');
reset role; select extensions.is((select count(*)::int from public.professional_availability_rules where clinic_member_id='45300000-0000-4000-8000-000000000002' and effective_from=date '2026-09-13' and is_active),3,'fixtures preserve effective date and member identity');
select extensions.finish(); rollback;
